"""Run bounded real shader/texture IPC regressions and preserve exit evidence."""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess
import uuid

ROOT = Path(__file__).resolve().parents[1]


def run(directory, count=2000):
    if not 112 <= count <= 100000:
        raise ValueError('count must cover a complete corpus and stay bounded')
    receipt = {'count_per_host_per_ring': count, 'executables': {}, 'tests': []}
    for role in ('client32', 'host32', 'host64'):
        exe = directory / ('shader-texture-' + role + '.exe')
        receipt['executables'][role] = hashlib.sha256(exe.read_bytes()).hexdigest()

    def save():
        (directory / 'test-receipt.json').write_text(json.dumps(receipt, indent=2) + '\n', encoding='utf-8')

    def single(mode, api=None):
        args = [str(directory / 'shader-texture-client32.exe'), str(uuid.uuid4()), mode]
        if api is not None:
            args.append(str(api))
        result = subprocess.run(args, capture_output=True, text=True, timeout=90)
        entry = {'mode': mode, 'api': api, 'exit': result.returncode,
                 'stdout': result.stdout, 'stderr': result.stderr}
        receipt['tests'].append(entry)
        print(result.stdout + result.stderr, end='', flush=True)
        save()
        if result.returncode or 'SHADER_TEXTURE_' not in result.stdout or '_PASS' not in result.stdout:
            raise RuntimeError('Shader/texture regression failed: ' + mode)

    try:
        single('wire')
        for mode in ('header-full', 'data-full', 'partial-space'):
            for api in range(7):
                single(mode, api)
        for role in ('host32', 'host64'):
            for mode in ('cross', 'cross-tight'):
                args = [str(uuid.uuid4()), mode, str(count)]
                processes = []
                entry = {'mode': mode, 'host_role': role, 'processes': []}
                try:
                    for current in (role, 'client32'):
                        process = subprocess.Popen([str(directory / ('shader-texture-' + current + '.exe')), *args],
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
                        processes.append(process)
                        entry['processes'].append({'role': current, 'pid': process.pid})
                    client_output = processes[1].communicate(timeout=90)[0]
                    host_output = processes[0].communicate(timeout=20)[0]
                    entry.update({'host_exit': processes[0].returncode, 'client_exit': processes[1].returncode,
                                  'host_stdout': host_output, 'client_stdout': client_output})
                    print(client_output + host_output, end='', flush=True)
                    if entry['host_exit'] or entry['client_exit'] or any(
                            'SHADER_TEXTURE_CROSS_PASS' not in output for output in (client_output, host_output)):
                        raise RuntimeError('Shader/texture cross-process regression failed: ' + role + ' ' + mode)
                finally:
                    for process, evidence in zip(processes, entry['processes']):
                        evidence['forced_cleanup'] = process.poll() is None
                        if evidence['forced_cleanup']:
                            process.kill()
                        process.wait()
                        evidence['final_exit'] = process.returncode
                        if process.stdout:
                            process.stdout.close()
                    entry['all_processes_reaped'] = all(p.poll() is not None for p in processes)
                    receipt['tests'].append(entry)
                    save()
        receipt['status'] = 'passed'
        print('SHADER_TEXTURE_ALL_PASS', flush=True)
    except Exception as error:
        receipt['status'] = 'failed'
        receipt['error'] = str(error)
        raise
    finally:
        save()


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--directory', type=Path, default=ROOT / '.deps/shader-texture-packets')
    parser.add_argument('--count', type=int, default=2000)
    args = parser.parse_args()
    run(args.directory.resolve(), args.count)
